test("amazon.deal_products: fields= returns a PartialModel", async (t) => {
  const mock = await MockServer.start();
  t.after(() => mock.close());
  const data = [{ platform: "amazon" }];
  mock.reply({ body: { data, page: { has_more: false, next_cursor: null, next_cursor_expires_at: null }, meta: {} } });
  const client = new SocialTap({ apiKey: API_KEY, baseURL: mock.url });
  const res = await client.amazon.dealProducts.list({ ...{}, fields: "platform" });
  const item = res.data[0]!;
  // A member left out by fields= is absent: the type must say so (tsc fails otherwise).
  const mayBeAbsent: undefined extends typeof item.platform ? true : false = true;
  assert.ok(mayBeAbsent);
  assert.deepEqual(res.data, data);
  assert.equal(mock.requests[0]!.query.get("fields"), "platform");
});

